  disk_container {
    description = "Imported disk image for debian12-erp-prod"
    format      = "VMDK"
    user_bucket {
      s3_bucket = "cloudmove-vm-import-staging"
      s3_key    = "images/debian12-erp-prod.vmdk"
    }
  }
  role_name = "vmimport"
  tags = {
    Name      = "debian12-erp-prod-snapshot"
    CMIR_ID   = "img-debian12-erp-prod-01"
    ManagedBy = "CloudMove"
  }
}

resource "aws_ami" "img_debian12_erp_prod_01" {
  name                = "debian12-erp-prod-ami"
  virtualization_type = "hvm"
  architecture        = "x86_64"
  boot_mode           = "uefi"
  root_device_name    = "/dev/sda1"
  ena_support         = true
  ebs_block_device {
    device_name = "/dev/sda1"
    snapshot_id = aws_ebs_snapshot_import.img_debian12_erp_prod_01_import.id
    volume_size = 170
    volume_type = "gp3"
  }
  tags = {
    Name      = "debian12-erp-prod-ami"
    CMIR_ID   = "img-debian12-erp-prod-01"
    ManagedBy = "CloudMove"
  }
}

# Migrated Resource: debian12-erp-prod-vm (vm-debian12-erp-prod)
resource "aws_instance" "vm_debian12_erp_prod" {
  ami                         = var.ami_id != "" ? var.ami_id : aws_ami.img_debian12_erp_prod_01.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_subnet.id
  vpc_security_group_ids      = [aws_security_group.app_sg.id]
