  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ============================================================
# AUTOMATICALLY GENERATED BY CLOUDMOVE MIGRATION ENGINE
# VARIABLES DEFINITION
# ============================================================

variable "aws_region" {
  description = "Target AWS Region"
  type        = string
