  name         = "app"
  machine_type = "e2-medium"
  zone         = var.gcp_zone
  tags         = ["cloudmove-workload"]
  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      size  = 50
      type  = "pd-balanced"
    }
  }
  network_interface {
    subnetwork = google_compute_subnetwork.primary_subnet.id
  }
  service_account {
    email  = google_service_account.workload_sa.email
    scopes = ["cloud-platform"]
  }
  labels = {
    cmir_id    = "app_app"
    managed_by = "cloudmove"
  }
}

# Migrated GCP Resource: app-app-host (compute-app-app)
resource "google_cloud_run_v2_service" "compute_app_app" {
