# ============================================================
# AUTOMATICALLY GENERATED BY CLOUDMOVE MIGRATION ENGINE
# GOOGLE CLOUD PLATFORM MAIN INFRASTRUCTURE MODULE
# ============================================================

# VPC Network & Subnetwork Boundaries
resource "google_compute_network" "target_vpc" {
  name                    = "cloudmove-target-vpc"
  auto_create_subnetworks = false
  routing_mode            = "REGIONAL"
}

resource "google_compute_subnetwork" "primary_subnet" {
  name                     = "cloudmove-primary-subnet"
  ip_cidr_range            = var.subnet_cidr
  region                   = var.gcp_region
  network                  = google_compute_network.target_vpc.id
  private_ip_google_access = true
}

resource "google_compute_firewall" "allow_internal_and_web" {
  name    = "cloudmove-allow-web-internal"
  network = google_compute_network.target_vpc.name
  allow {
    protocol = "tcp"
    ports    = ["22", "80", "443", "5432", "6379", "8000", "8080"]
  }
  source_ranges = ["10.0.0.0/8"]
  target_tags   = ["cloudmove-workload"]
}

resource "google_service_account" "workload_sa" {
  account_id   = "cloudmove-workload-sa"
  display_name = "CloudMove Migrated Workload Service Account"
}

# Migrated GCP Resource: app-runtime-host (compute-app-host)
resource "google_cloud_run_v2_service" "compute_app_host" {
  name     = "app-runtime-host"
  location = var.gcp_region
  template {
    service_account = google_service_account.workload_sa.email
    containers {
      image = "us-docker.pkg.dev/cloudrun/container/hello"
    }
  }
}

# Migrated GCP Resource: app (app-app)
resource "google_compute_instance" "app_app" {
  name         = "app"
  machine_type = "e2-medium"
  zone         = var.gcp_zone
  tags         = ["cloudmove-workload"]
  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      size  = 50
      type  = "pd-balanced"
    }
  }
  network_interface {
    subnetwork = google_compute_subnetwork.primary_subnet.id
  }
  service_account {
    email  = google_service_account.workload_sa.email
    scopes = ["cloud-platform"]
  }
  labels = {
    cmir_id    = "app_app"
    managed_by = "cloudmove"
  }
}

# Migrated GCP Resource: app-app-host (compute-app-app)
resource "google_cloud_run_v2_service" "compute_app_app" {
  name     = "app-app-host"
  location = var.gcp_region
  template {
    service_account = google_service_account.workload_sa.email
    containers {
      image = "us-docker.pkg.dev/cloudrun/container/hello"
    }
  }
}

# Migrated GCP Resource: app-app (app-app-app)
resource "google_compute_instance" "app_app_app" {
  name         = "app-app"
  machine_type = "e2-medium"
  zone         = var.gcp_zone
  tags         = ["cloudmove-workload"]
  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      size  = 50
      type  = "pd-balanced"
    }
  }
  network_interface {
    subnetwork = google_compute_subnetwork.primary_subnet.id
  }
  service_account {
    email  = google_service_account.workload_sa.email
    scopes = ["cloud-platform"]
  }
  labels = {
    cmir_id    = "app_app_app"
    managed_by = "cloudmove"
  }
}

# Migrated GCP Resource: app-postgres-host (compute-app-postgres)
resource "google_cloud_run_v2_service" "compute_app_postgres" {
  name     = "app-postgres-host"
  location = var.gcp_region
  template {
    service_account = google_service_account.workload_sa.email
    containers {
      image = "us-docker.pkg.dev/cloudrun/container/hello"
    }
  }
}

# Migrated GCP Resource: app-postgres (app-app-postgres)
resource "google_compute_instance" "app_app_postgres" {
  name         = "app-postgres"
  machine_type = "e2-medium"
  zone         = var.gcp_zone
  tags         = ["cloudmove-workload"]
  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      size  = 50
      type  = "pd-balanced"
    }
  }
  network_interface {
    subnetwork = google_compute_subnetwork.primary_subnet.id
  }
  service_account {
    email  = google_service_account.workload_sa.email
    scopes = ["cloud-platform"]
  }
  labels = {
    cmir_id    = "app_app_postgres"
    managed_by = "cloudmove"
  }
}

# Migrated GCP Resource: app-redis-host (compute-app-redis)
resource "google_cloud_run_v2_service" "compute_app_redis" {
  name     = "app-redis-host"
  location = var.gcp_region
  template {
    service_account = google_service_account.workload_sa.email
    containers {
      image = "us-docker.pkg.dev/cloudrun/container/hello"
    }
  }
}

# Migrated GCP Resource: app-redis (app-app-redis)
resource "google_compute_instance" "app_app_redis" {
  name         = "app-redis"
  machine_type = "e2-medium"
  zone         = var.gcp_zone
  tags         = ["cloudmove-workload"]
  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      size  = 50
      type  = "pd-balanced"
    }
  }
  network_interface {
    subnetwork = google_compute_subnetwork.primary_subnet.id
  }
  service_account {
    email  = google_service_account.workload_sa.email
    scopes = ["cloud-platform"]
  }
  labels = {
    cmir_id    = "app_app_redis"
    managed_by = "cloudmove"
  }
}

# Migrated GCP Resource: tcp-8080 (port-app-8080)
# Migrated GCP Resource: app-workload-identity (identity-app-sa)
# Migrated GCP Resource: app-postgresql (dep-app-postgresql)
resource "google_sql_database_instance" "dep_app_postgresql" {
  name                = "app-postgresql-sql"
  database_version    = "POSTGRES_15"
  region              = var.gcp_region
  deletion_protection = false
  settings {
    tier              = "db-custom-2-4096"
    availability_type = "REGIONAL"
    disk_type         = "PD_SSD"
    disk_size         = 20
    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.target_vpc.id
    }
    user_labels = {
      cmir_id    = "dep_app_postgresql"
      managed_by = "cloudmove"
    }
  }
}

# Migrated GCP Resource: app-redis (dep-app-redis)
resource "google_redis_instance" "dep_app_redis" {
  name               = "app-redis-redis"
  tier               = "BASIC"
  memory_size_gb     = 1
  region             = var.gcp_region
  authorized_network = google_compute_network.target_vpc.id
  redis_version      = "REDIS_7_0"
  labels = {
    cmir_id    = "dep_app_redis"
    managed_by = "cloudmove"
  }
}

# Migrated GCP Resource: app-invoices-bucket (dep-app-object-storage)
resource "google_storage_bucket" "dep_app_object_storage" {
  name                        = "cloudmove-app-invoices-bucket"
  location                    = var.gcp_region
  uniform_bucket_level_access = true
  force_destroy               = true
  labels = {
    cmir_id    = "dep_app_object_storage"
    managed_by = "cloudmove"
  }
}

# Migrated GCP Resource: external-endpoint-external-api-url (dep-app-ext-external-api-url)

