  name = "srv-billing-api-02-os-(red-hat-enterprise-linux-9-4)-image"
  raw_disk {
    source = "gs://cloudmove-vm-images/srv-billing-api-02-os-(red-hat-enterprise-linux-9-4).tar.gz"
  }
  guest_os_features {
    type = "UEFI_COMPATIBLE"
  }
  guest_os_features {
    type = "VIRTIO_SCSI_MULTIQUEUE"
  }
  guest_os_features {
    type = "GVNIC"
  }
  labels = {
    cmir_id    = "os_asset_vm_middleware_rhel_02"
    managed_by = "cloudmove"
  }
}

# Migrated GCP Resource: sshd (listening :22) (proc-asset-vm-Middleware-rhel-02-sshd)
resource "google_compute_instance" "proc_asset_vm_middleware_rhel_02_sshd" {
  name         = "sshd-(listening-:22)"
  machine_type = "e2-medium"
  zone         = var.gcp_zone
  tags         = ["cloudmove-workload"]
  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      size  = 50
      type  = "pd-balanced"
    }
  }
  network_interface {
    subnetwork = google_compute_subnetwork.primary_subnet.id
  }
  service_account {
    email  = google_service_account.workload_sa.email
    scopes = ["cloud-platform"]
  }
  labels = {
    cmir_id    = "proc_asset_vm_middleware_rhel_02_sshd"
    managed_by = "cloudmove"
  }
}

# Migrated GCP Resource: app-worker.service (svc-asset-vm-Middleware-rhel-02)
